package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StringUtils.indexOfAny(String str, String[] searchStrs)
 * to maximize branch and line coverage.
 */
public class StringUtils_indexOfAny_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAny_NullStr() {
        String[] searchStrs = {"a", "b"};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(null, searchStrs));
    }

    @Test
    public void testIndexOfAny_NullSearchStrs() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", null));
    }

    @Test
    public void testIndexOfAny_EmptySearchStrs() {
        String[] searchStrs = {};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_NullElementInSearchStrs() {
        // Should skip null elements in the array
        String[] searchStrs = {null, "b"};
        assertEquals(1, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_NoMatchFound() {
        String[] searchStrs = {"x", "y", "z"};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_SingleMatch() {
        String[] searchStrs = {"b"};
        assertEquals(1, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_MultipleMatches_ReturnsFirstOccurrence() {
        // "b" is at index 1, "a" is at index 0. Should return 0.
        String[] searchStrs = {"b", "a"};
        assertEquals(0, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_MultipleMatches_ReturnsEarliestIndex() {
        // "bc" at index 1, "ab" at index 0
        String[] searchStrs = {"bc", "ab"};
        assertEquals(0, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_MatchAtEnd() {
        String[] searchStrs = {"c"};
        assertEquals(2, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_EmptyStringStr() {
        String[] searchStrs = {"a"};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("", searchStrs));
    }

    @Test
    public void testIndexOfAny_EmptyStringInSearchStrs() {
        // str.indexOf("") returns 0
        String[] searchStrs = {""};
        assertEquals(0, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_AllNullSearchStrs() {
        String[] searchStrs = {null, null};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", searchStrs));
    }
}
